namespace ghidra.file.formats.ios.ibootim;






using ghidra.app.util.bin;
using ghidra.app.util.bin;
using ghidra.file.formats.lzss;
using ghidra.file.image;
using ghidra.file.image;
using ghidra.formats.gfilesystem;
using ghidra.formats.gfilesystem.annotations;
using ghidra.formats.gfilesystem.factory;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;

/* @FileSystemInfo(type = "ibootim", description = "iOS " +
	iBootImConstants.SIGNATURE, factory = typeof(GFileSystemBaseFactory)) */
public class iBootImFileSystem : GFileSystemBase, GIconProvider {

	private iBootImHeader header;
	private List<GFile> fileList = new();
	private byte[] bytes = new byte[0];

	public iBootImFileSystem(string fileSystemName, ByteProvider provider) : base(fileSystemName, provider)
    {
	}

	/* @Override */
	public void close()
    {
		bytes = new byte[0];
	}

	/* @Override */
	public ByteProvider getByteProvider(GFile file, TaskMonitor monitor) {
		return new ByteArrayProvider(bytes, file.getFSRL());
	}

	/* @Override */
	public Icon getIcon(GFile file, TaskMonitor monitor)
    {
		using (InputStream cacheInputStream = new ByteArrayInputStream(bytes))
{
			GImageFormat format = (header.getFormat() == iBootImConstants.FORMAT_ARGB)
					? GImageFormat.RGB_ALPHA_4BYTE
					: GImageFormat.GRAY_ALPHA_2BYTE;
			GImage image = new GImage(header.getWidth(), header.getHeight(), format,
				cacheInputStream, bytes.length);
			return image.toPNG();
		}
	}

	/* @Override */
	public List<GFile> getListing(GFile directory)
    {
		if (directory == null || directory.equals(root)) {
			return fileList;
		}
		return new();
	}

	/* @Override */
	public bool isValid(TaskMonitor monitor)
    {
		byte[] signatureBytes = provider.readBytes(0, iBootImConstants.SIGNATURE_LENGTH);
		return Arrays.equals(signatureBytes, iBootImConstants.SIGNATURE_BYTES);
	}

	/* @Override */
	public void open(TaskMonitor monitor)
    {
		monitor.setMessage("Opening iBoot Image...");

		this.header = new iBootImHeader(provider);

		byte[] compressedBytes = provider.readBytes(iBootImConstants.HEADER_LENGTH,
			provider.length() - iBootImConstants.HEADER_LENGTH);
		ByteArrayOutputStream decompressedBytes = new ByteArrayOutputStream();
		LzssCodec.decompress(decompressedBytes, new ByteArrayInputStream(compressedBytes));
		bytes = decompressedBytes.toByteArray();

		string name = StringUtilities.toString(header.getFormat()) + "_image";

		GFileImpl file =
			GFileImpl.fromFilename(this, root, name, false, decompressedBytes.size(), null);

		fileList.add(file);
	}

}
